  "leas-credentials": "name: leas-credentials\n\n# The expiry watch.\n#\n# Distribution certificates last three years and provisioning profiles one.\n# That is long enough that nobody remembers and short enough that everybody is\n# eventually caught, so the only reliable reminder is a scheduled one. This job\n# reads the expiry dates out of your own secrets and opens an issue before the\n# date arrives — and closes it again once you have renewed.\n\non:\n  schedule:\n    - cron: '0 14 * * 1'   # Mondays, 14:00 UTC\n  workflow_dispatch:\n    inputs:\n      days:\n        description: Warn this many days ahead\n        type: string\n        default: '30'\n\npermissions:\n  contents: read\n  issues: write\n\njobs:\n  check:\n    # Linux is enough. leas falls back to openssl for the provisioning profile\n    # when macOS's `security` is absent, so this does not need a rented Mac.\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with: { node-version: 22, cache: npm }\n      - uses: actions/setup-java@v4\n        with: { distribution: temurin, java-version: 17 }\n\n      - run: npm ci\n\n      - name: Read credential expiry\n        id: scan\n        env:\n          DAYS: ${{ inputs.days || '30' }}\n          LEAS_IOS_DIST_CERT_BASE64: ${{ secrets.LEAS_IOS_DIST_CERT_BASE64 }}\n          LEAS_IOS_DIST_CERT_PASSWORD: ${{ secrets.LEAS_IOS_DIST_CERT_PASSWORD }}\n          LEAS_IOS_PROVISIONING_PROFILE_BASE64: ${{ secrets.LEAS_IOS_PROVISIONING_PROFILE_BASE64 }}\n          LEAS_ANDROID_KEYSTORE_BASE64: ${{ secrets.LEAS_ANDROID_KEYSTORE_BASE64 }}\n          LEAS_ANDROID_KEYSTORE_PASSWORD: ${{ secrets.LEAS_ANDROID_KEYSTORE_PASSWORD }}\n          LEAS_ANDROID_KEY_ALIAS: ${{ secrets.LEAS_ANDROID_KEY_ALIAS }}\n        run: |\n          npx leas creds --days \"$DAYS\" || true          # readable in the run log\n          npx leas creds --days \"$DAYS\" --json > creds.json\n          node --input-type=module -e '\n            import { readFileSync, writeFileSync, appendFileSync } from \"node:fs\";\n            const r = JSON.parse(readFileSync(\"creds.json\", \"utf8\"));\n            const bad = r.credentials.filter((c) => c.status === \"expired\" || c.status === \"expiring\");\n            appendFileSync(process.env.GITHUB_OUTPUT, `attention=${bad.length}\\n`);\n            const line = (c) => `- **${c.kind}** (${c.platform}) — ` + (c.status === \"expired\"\n              ? `**expired ${c.expires.slice(0, 10)}**`\n              : `expires ${c.expires.slice(0, 10)}, in ${c.daysLeft} days`)\n              + (c.identity ? `\\n  \\`${c.identity}\\`` : \"\");\n            writeFileSync(\"issue.md\", [\n              `${bad.length} signing credential${bad.length === 1 ? \" needs\" : \"s need\"} attention.`, \"\",\n              ...bad.map(line), \"\",\n              \"Renewal runbooks are in section 8 of the manual. After renewing, update the\",\n              \"matching repository secret and this issue will close itself on the next run.\", \"\",\n              `_Checked ${r.generatedAt.slice(0, 10)} · window ${r.warnDays} days._`,\n            ].join(\"\\n\"));\n          '\n\n      - name: Open or update the issue\n        if: steps.scan.outputs.attention != '0'\n        env:\n          GH_TOKEN: ${{ github.token }}\n        run: |\n          gh label create leas-credentials --color D93F0B \\\n            --description \"Signing material approaching expiry\" 2>/dev/null || true\n          NUM=$(gh issue list --label leas-credentials --state open --json number --jq '.[0].number // empty')\n          if [ -n \"$NUM\" ]; then\n            gh issue comment \"$NUM\" --body-file issue.md\n          else\n            gh issue create --title \"Signing credentials need attention\" \\\n              --label leas-credentials --body-file issue.md\n          fi\n\n      - name: Close the issue once everything is renewed\n        if: steps.scan.outputs.attention == '0'\n        env:\n          GH_TOKEN: ${{ github.token }}\n        run: |\n          NUM=$(gh issue list --label leas-credentials --state open --json number --jq '.[0].number // empty')\n          if [ -n \"$NUM\" ]; then\n            gh issue close \"$NUM\" --comment \"All signing credentials are valid again.\"\n          fi\n",
